<!DOCTYPE html>
<html>
<?php include('head.php');
$date = DateTime::createFromFormat('!Y-m-d', (string) filter_input(INPUT_GET,'date')) ?: new DateTime('today');
$dayStart=$date->format('Y-m-d 00:00:00');$dayEndDate=clone $date;$dayEndDate->modify('+1 day');$dayEnd=$dayEndDate->format('Y-m-d 00:00:00');
$rows = $db->exec("SELECT t.IdTelaio loomId,t.NomeTelaio loomName,SUM(s.StopCount) stopCount,SUM(s.StopSeconds) stopSeconds,COALESCE(e.meters,0) meters FROM loom_stop_window_summary s JOIN telaio t ON t.IdTelaio=s.LoomId AND t.EnableTelaio=1 LEFT JOIN (SELECT IdTelaio,GREATEST(MAX(LunghezzaDaInizio)-MIN(LunghezzaDaInizio),0)/1000 meters FROM evento FORCE INDEX(index_evento_Timestamp) WHERE Timestamp>=? AND Timestamp<? GROUP BY IdTelaio) e ON e.IdTelaio=t.IdTelaio WHERE s.SummaryDate=? AND s.WindowCode IN ('s1','s2','s3') GROUP BY t.IdTelaio,t.NomeTelaio,e.meters ORDER BY stopSeconds DESC",array(1=>$dayStart,2=>$dayEnd,3=>$date->format('Y-m-d')));
$total=0;$totalMeters=0;$estimatedLostMeters=0; foreach($rows as $row){$total+=(int)$row['stopSeconds'];$totalMeters+=(float)$row['meters'];$available=max(86400-(int)$row['stopSeconds'],1);$estimatedLostMeters+=(float)$row['meters']*(int)$row['stopSeconds']/$available;}
$meterLossPercent=($totalMeters+$estimatedLostMeters)>0?round($estimatedLostMeters*100/($totalMeters+$estimatedLostMeters),2):0;
function lossDuration($s){$s=(int)$s;return floor($s/3600).' sa '.floor(($s%3600)/60).' dk';}
?>
<body class="management-report-page"><div id="wrapper"><nav id="nave" class="navbar navbar-inverse navbar-fixed-top"><?php include('header.php');include('sidebar.php');?></nav><div id="page-wrapper" class="management-report-wrapper"><main class="management-report-shell">
<header class="management-report-heading"><div><span>ÜRETİM YÖNETİMİ</span><h1>Verim Kaybı Analizi</h1><p>Duruşlardan kaynaklanan kayıp çalışma zamanını gösterir.</p></div></header>
<form class="management-report-controls"><label>Tarih<input name="date" type="date" value="<?php echo $date->format('Y-m-d');?>"></label><button><i class="fa fa-refresh"></i> Analizi getir</button></form>
<section class="management-kpis"><article><span>Etkilenen tezgâh</span><strong><?php echo count($rows);?></strong></article><article><span>Metraj Kayıp Oranı</span><strong><?php echo number_format($meterLossPercent,2,',','.');?> %</strong><small>Günün toplam üretimine göre</small></article><article><span>Toplam Metraj Kaybı</span><strong><?php echo number_format($estimatedLostMeters,2,',','.');?> m</strong></article><article><span>Günlük gerçekleşen metraj</span><strong><?php echo number_format($totalMeters,2,',','.');?> m</strong></article></section>
<section class="management-panel"><header><h2>Tezgâh bazlı kayıp</h2><small>Metraj kaybı, gerçekleşen metrajın tezgâhın duruş dışı çalışma zamanına oranı üzerinden tahmini hesaplanır.</small></header><div class="management-table-scroll"><table data-report-table><thead><tr><th>Tezgâh</th><th>Duruş</th><th>Kayıp zaman</th><th>Tahmini metraj kaybı</th></tr></thead><tbody><?php foreach($rows as $row){$available=max(86400-(int)$row['stopSeconds'],1);$lost=(float)$row['meters']*(int)$row['stopSeconds']/$available;?><tr><td><b><?php echo (int)$row['loomId'];?></b> <?php echo htmlspecialchars($row['loomName']);?></td><td><?php echo (int)$row['stopCount'];?></td><td><?php echo lossDuration($row['stopSeconds']);?></td><td><?php echo number_format($lost,2,',','.');?> m</td></tr><?php }?></tbody></table></div></section>
</main></div></div><?php include('footer.php');?><link rel="stylesheet" href="css/management-reports.css"><link rel="stylesheet" href="css/report-table-sort.css"><script src="js/report-table-sort.js"></script></body></html>
